static int length(char*s){int n;n=0;while(s[n])n=n+1;return n;}static int same(char*a,char*b){int i;i=0;while(a[i]&&b[i]){if(a[i]!=b[i])return 0;i=i+1;}return a[i]==b[i];}
char*multiply_strings(char*a,char*b){static char result[256];int digits[256];int n;int m;int i;int j;int carry;int value;int start;int out;n=length(a);m=length(b);for(i=0;i<n+m;i=i+1)digits[i]=0;for(i=n-1;i>=0;i=i-1){for(j=m-1;j>=0;j=j-1){digits[i+j+1]=digits[i+j+1]+(a[i]-'0')*(b[j]-'0');}}for(i=n+m-1;i>0;i=i-1){carry=digits[i]/10;digits[i]=digits[i]%10;digits[i-1]=digits[i-1]+carry;}start=0;while(start<n+m-1&&digits[start]==0)start=start+1;out=0;for(i=start;i<n+m;i=i+1){value=digits[i];result[out]=(char)('0'+value);out=out+1;}result[out]='\0';return result;}
int main(void){if(!same(multiply_strings("2","3"),"6"))return 1;if(!same(multiply_strings("123","456"),"56088"))return 2;if(!same(multiply_strings("0","52"),"0"))return 3;if(!same(multiply_strings("999","999"),"998001"))return 4;return 42;}
